import { existsSync } from 'node:fs';
import { join } from 'node:path';
import {
  RspackConfigMutator,
  RspackConfigTransformer,
} from '@teambit/rspack.modules.rspack-config-mutator';

/**
 * Makes `react-dom/profiling` resolve to `react-dom/client`. That's it.
 *
 * Why anything imports profiling at all: the mounter and docs template must
 * run on React 17, 18 and 19, and `react-dom/profiling` is the only entry
 * that resolves on all three. Importing `react-dom/client` would break React
 * 17 builds, so they can't.
 *
 * Why we redirect it: the profiling build is the slow, bigger react-dom.
 * The client build is the normal, fast one. Same createRoot, better build.
 * And if component code imports `react-dom/client` itself (portals, custom
 * roots), both requests now hit the SAME file — one react-dom on the page,
 * not two. Two react-doms = ~190kb extra and double init. Bad.
 *
 * Where client.js comes from: the `react-dom` peer alias. That alias IS the
 * react-dom copy this bundle uses, so taking client.js from inside it can
 * never mix copies. No alias, or no client.js in it (React 17)? Skip. Skipping
 * is always safe — previews still render, just on the profiling build.
 */
export function createReactDomProfilingToClientAliasTransformer(): RspackConfigTransformer {
  return (configMutator: RspackConfigMutator) => {
    const config = configMutator.raw;
    const debug = process.env.BIT_REACT_DOM_PROFILING_TO_CLIENT_ALIAS_DEBUG;

    const aliasMap = config.resolve?.alias;
    const reactDomDir =
      aliasMap && !Array.isArray(aliasMap)
        ? (aliasMap as Record<string, unknown>)['react-dom']
        : undefined;
    if (typeof reactDomDir !== 'string') {
      if (debug) console.error('[react-dom-profiling-to-client-alias] no react-dom alias; skipping');
      return configMutator;
    }
    const clientPath = join(reactDomDir, 'client.js');
    if (!existsSync(clientPath)) {
      // React 17 — no client entry; leave react-dom/profiling untouched (the
      // mounter never loads it there, having taken the legacy-render branch).
      if (debug) console.error('[react-dom-profiling-to-client-alias] no client entry (react 17):', reactDomDir);
      return configMutator;
    }

    // the peer-sharing prefix alias for 'react-dom' is matched in insertion
    // order — an exact 'react-dom/profiling$' key merged after it never gets
    // consulted. rebuild the alias map with the exact key FIRST so it wins.
    config.resolve!.alias = {
      'react-dom/profiling$': clientPath,
      ...(aliasMap as Record<string, unknown>),
    };
    if (debug) console.error('[react-dom-profiling-to-client-alias] aliased react-dom/profiling ->', clientPath);
    return configMutator;
  };
}
